# Boolean search: shunting-yard parse of AND/OR/NOT with parens, evaluated over doc term sets.
docs = {'d1': 'archive index catalog', 'd2': 'archive notes', 'd3': 'index of maps'}
def tokenize(expr):
    out, i = [], 0
    while i < len(expr):
        c = expr[i]
        if c.isspace(): i += 1; continue
        if c in "()": out.append(c); i += 1; continue
        j = i
        while j < len(expr) and (expr[j].isalnum() or expr[j] in "_-"): j += 1
        out.append(expr[i:j].lower()); i = j
    return out
def to_rpn(toks):
    prec = {"not": 3, "and": 2, "or": 1}; out, ops = [], []
    for t in toks:
        if t == "(": ops.append(t)
        elif t == ")":
            while ops and ops[-1] != "(": out.append(ops.pop())
            ops.pop()
        elif t in prec:
            while ops and ops[-1] != "(" and prec.get(ops[-1], 0) >= prec[t]: out.append(ops.pop())
            ops.append(t)
        else: out.append(("term", t))
    while ops: out.append(ops.pop())
    return out
def eval_rpn(rpn, terms):
    st = []
    for t in rpn:
        if isinstance(t, tuple): st.append(t[1] in terms)
        elif t == "not": st.append(not st.pop())
        elif t == "and": b, a = st.pop(), st.pop(); st.append(a and b)
        elif t == "or": b, a = st.pop(), st.pop(); st.append(a or b)
    return st[0]
expr = "archive AND index"
rpn = to_rpn(tokenize(expr))
print("Expression:", expr)
for doc_id, text in docs.items():
    terms = set(text.lower().split())
    if eval_rpn(rpn, terms):
        print("MATCH:", doc_id, "-", text[:55])

